import{_ as o,a as t,c as n,ac as a}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第二册：实践与进步 · 单元 4 语法总结 · 现在完成时与过去时间至动名词与动词搭配","description":"L73–L96 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 4 语法总结 · 现在完成时与过去时间至动名词与动词搭配","description":"L73–L96 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-04/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 4 语法总结","summary":"L73–L96 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 4 语法总结","link":"/life/english/new-concept/book-2/unit-04/grammar"},"next":{"text":"第二册：实践与进步 · 单元 4 语法总结 · 时间、原因与让步从句至将来进行时与过程","link":"/life/english/new-concept/book-2/unit-04/grammar-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 4 语法总结","link":"/life/english/new-concept/book-2/unit-04/grammar"},"next":{"text":"第二册：实践与进步 · 单元 4 语法总结 · 时间、原因与让步从句至将来进行时与过程","link":"/life/english/new-concept/book-2/unit-04/grammar-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/grammar-part-01.md","filePath":"life/english/new-concept/book-2/unit-04/grammar-part-01.md"}'),i={name:"life/english/new-concept/book-2/unit-04/grammar-part-01.md"};function r(s,e,h,l,p,c){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="第二册-实践与进步-·-单元-4-语法总结-·-现在完成时与过去时间至动名词与动词搭配" tabindex="-1">第二册：实践与进步 · 单元 4 语法总结 · 现在完成时与过去时间至动名词与动词搭配 <a class="header-anchor" href="#第二册-实践与进步-·-单元-4-语法总结-·-现在完成时与过去时间至动名词与动词搭配" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 4 语法总结 · 现在完成时与过去时间至动名词与动词搭配&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-04/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元复习与自测</a></p><h2 id="第二册-实践与进步-·-单元-4-语法总结" tabindex="-1">第二册：实践与进步 · 单元 4 语法总结 <a class="header-anchor" href="#第二册-实践与进步-·-单元-4-语法总结" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 4 语法总结 {#第二册-实践与进步-·-单元-4-语法总结}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-2/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元复习与自测</a></p><h2 id="现在完成时与过去时间" tabindex="-1">现在完成时与过去时间 <a class="header-anchor" href="#现在完成时与过去时间" aria-label="Permalink to &quot;现在完成时与过去时间 {#现在完成时与过去时间}&quot;">​</a></h2><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：has travelled alone three times 是截至现在的经历次数；has been travelling 强调过程。alone 指没有同行者，不等于没有任何服务人员提供帮助。</p><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：has recovered 表已有恢复结果，但不必然表示所有功能恢复。具体限制可用 still、yet 补充，避免“成功”一词覆盖全部后续情况。</p><p><strong>L73 原创例句：</strong> Ella has crossed the border with her family five times this year.</p><p>埃拉今年已经和家人一起过境五次了。</p><p><strong>L77 原创例句：</strong> The injured bird has recovered enough to stand on both feet.</p><p>那只受伤的鸟已经恢复到能够双脚站立的程度。</p><p><strong>易错：</strong> five time 应为 five times；不要把 times 误译成五点钟。</p><p>enough healthy 的次序不对；形容词后放 enough，如 healthy enough。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-073">Lesson 73</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-077">Lesson 77</a></p><h2 id="定语从句与指代" tabindex="-1">定语从句与指代 <a class="header-anchor" href="#定语从句与指代" aria-label="Permalink to &quot;定语从句与指代 {#定语从句与指代}&quot;">​</a></h2><p>定语从句跟在被修饰名词之后，用 who、which、that 等连接并在从句内承担成分。限制性从句帮助确定“是哪一个”，非限制性从句用逗号补充信息。关系代词作宾语时，在限制性从句中常可省略；作主语时不能省略。先确定先行词，再检查从句缺主语、宾语还是状语，避免同时保留一个多余的 he、it 或 them。本课应用：who recognised her 限定是哪位游客，关系代词在从句中作主语不能省略。若改为 she recognised，缺的是宾语，结构会不同。</p><p>定语从句跟在被修饰名词之后，用 who、which、that 等连接并在从句内承担成分。限制性从句帮助确定“是哪一个”，非限制性从句用逗号补充信息。关系代词作宾语时，在限制性从句中常可省略；作主语时不能省略。先确定先行词，再检查从句缺主语、宾语还是状语，避免同时保留一个多余的 he、it 或 them。本课应用：which was donated ... 补充物品来源，若用逗号是非限制性说明；主句仍需独立谓语 stands。不能把整个句子停在 which 从句结束处。</p><p><strong>L74 原创例句：</strong> The visitor who recognised the actor kept her secret.</p><p>认出演员的那位游客替她保守了秘密。</p><p><strong>L93 原创例句：</strong> The statue, which was donated by local artists, stands beside the library.</p><p>这座由当地艺术家捐赠的雕像立在图书馆旁。</p><p><strong>易错：</strong> The visitor who recognised the actor smiled. 中 who 作 recognised 的主语，意思是“认出演员的那位游客笑了”。The visitor who he recognised smiled. 也合法：he 作从句主语，who 作宾语，意思是“他认出的那位游客笑了”。若要表达前一种意思，不能写 The visitor who he recognised the actor smiled.；从句已有主语 he 和宾语 the actor，再加 who 会造成成分重复。</p><p>非限制性从句通常不能用 that 替代 which，也不能省略关系代词。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-074">Lesson 74</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-093">Lesson 93</a></p><h2 id="不定式与目的" tabindex="-1">不定式与目的 <a class="header-anchor" href="#不定式与目的" aria-label="Permalink to &quot;不定式与目的 {#不定式与目的}&quot;">​</a></h2><p>to 加动词原形可以作某些动词的宾语、名词后的修饰语或表示目的的状语。表示目的时，执行不定式动作的人通常与主句主语一致；不一致时需明确另一个逻辑主语，如 for somebody to do。否定一般写 not to do。情态动词后、make/let 主动结构中通常用不带 to 的原形，不能因为看到两个动词就一律在中间加入 to。本课应用：to attract attention 表摆放标记的目的；目的主语与放置者相同。so that 从句可更明确引出另一执行者，如 pilots could see it。</p><p>to 加动词原形可以作某些动词的宾语、名词后的修饰语或表示目的的状语。表示目的时，执行不定式动作的人通常与主句主语一致；不一致时需明确另一个逻辑主语，如 for somebody to do。否定一般写 not to do。情态动词后、make/let 主动结构中通常用不带 to 的原形，不能因为看到两个动词就一律在中间加入 to。本课应用：too ... to 通常表示程度高到不能做某事；not too ... to 否定这个障碍。不能把任何 too 都译成非常，它常含超出合适程度。</p><p><strong>L75 原创例句：</strong> The hikers laid bright jackets on the rocks to attract attention.</p><p>徒步者把鲜艳的外套铺在岩石上，以吸引注意。</p><p><strong>L85 原创例句：</strong> Ruth was nervous, but she was not too old to learn coding.</p><p>露丝很紧张，但她并没有老到不能学习编程。</p><p><strong>易错：</strong> lie 表躺下，过去式 lay；lay 表放置，过去式 laid，本例需要有宾语的 laid。</p><p>enough confident 语序错误，应为 confident enough；too old 与 very old 意义不同。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-075">Lesson 75</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-085">Lesson 85</a></p><h2 id="间接引语与视角转换" tabindex="-1">间接引语与视角转换 <a class="header-anchor" href="#间接引语与视角转换" aria-label="Permalink to &quot;间接引语与视角转换 {#间接引语与视角转换}&quot;">​</a></h2><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：claimed that 明确有人作出声称，不等于内容成立；reported that 也不自动保证真实，应结合来源和验证信息。</p><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：asked where he had been 把待核对经历放在问话之前；不能用 where had he been 的倒装语序。转述一个说法不等于已经证实。</p><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：I do not think ... 常把否定放在 think 前，意义近于认为从句不成立；不能据此说每个 think 后的否定都必须前移。</p><p><strong>L76 原创例句：</strong> The programme claimed that the trees could grow blue apples.</p><p>节目声称那些树能结出蓝色苹果。</p><p><strong>L87 原创例句：</strong> The officer asked where Daniel had been before eight.</p><p>警官问丹尼尔八点以前在哪里。</p><p><strong>L92 原创例句：</strong> I do not think the receptionist meant to be rude.</p><p>我认为接待员不是有意无礼。</p><p><strong>易错：</strong> believe a person 表相信其所说，believe in a person 更偏信任其能力或品格。</p><p>He said ... 不等于 It was proved ...；陈述和证据必须分别标识。</p><p>rude 是形容词，rudely 是副词；meant to be 后用 rude，不是 rudely。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-076">Lesson 76</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-087">Lesson 87</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-092">Lesson 92</a></p><h2 id="动名词与动词搭配" tabindex="-1">动名词与动词搭配 <a class="header-anchor" href="#动名词与动词搭配" aria-label="Permalink to &quot;动名词与动词搭配 {#动名词与动词搭配}&quot;">​</a></h2><p>动词的 -ing 形式可像名词一样作主语或宾语，常出现在 enjoy、avoid、finish 等动词之后，以及介词之后。它仍能带自己的宾语或状语。另一些动词通常接 to 不定式，不能按中文意思随意互换；stop、remember、try 等词接两种形式时意思还可能改变。遇到 to 先判断它是不定式标记还是介词，再决定后面使用原形还是 -ing。本课应用：stop buying 是停止购买行为，stop to buy 是停下别的活动去购买。改变习惯时还可用 avoid doing，不能把两种 stop 结构当同义。</p><p><strong>L78 原创例句：</strong> Jon stopped buying cigarettes on his way to work.</p><p>乔恩停止了在上班路上买烟的习惯。</p><p><strong>易错：</strong> He stopped to buy cigarettes 表示停下来买烟，意思与停止买烟相反。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-078">Lesson 78</a></p>',55)])])}const f=o(i,[["render",r]]);export{d as __pageData,f as default};
